package ec.edu.scli.reservas.infrastructure.persistence.entity;
import ec.edu.scli.reservas.domain.model.EstadoSolicitudCambio; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="revisiones_solicitud_cambio") public class RevisionSolicitudCambioJpaEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; private UUID solicitudId,pisoId,revisorPerfilId; @Enumerated(EnumType.STRING) private EstadoSolicitudCambio estado=EstadoSolicitudCambio.PENDIENTE; @Column(columnDefinition="TEXT") private String observacion; private Instant creadaEn,resueltaEn; @PrePersist void crear(){if(creadaEn==null)creadaEn=Instant.now();} public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getSolicitudId(){return solicitudId;} public void setSolicitudId(UUID v){solicitudId=v;} public UUID getPisoId(){return pisoId;} public void setPisoId(UUID v){pisoId=v;} public UUID getRevisorPerfilId(){return revisorPerfilId;} public void setRevisorPerfilId(UUID v){revisorPerfilId=v;} public EstadoSolicitudCambio getEstado(){return estado;} public void setEstado(EstadoSolicitudCambio v){estado=v;} public String getObservacion(){return observacion;} public void setObservacion(String v){observacion=v;} public Instant getCreadaEn(){return creadaEn;} public Instant getResueltaEn(){return resueltaEn;} public void setResueltaEn(Instant v){resueltaEn=v;} }
